-- Preserve literal-prefix checks without exceeding D1 GLOB pattern limits.
DROP TRIGGER IF EXISTS continuous_notice_status_attempt_insert;
CREATE TRIGGER IF NOT EXISTS continuous_notice_status_attempt_insert BEFORE INSERT ON continuous_notice_status_attempts
WHEN NOT EXISTS(SELECT 1 FROM continuous_review_notice_close n JOIN stable_workbook_claims c ON c.spreadsheet_id=n.spreadsheet_id AND c.operation_token=n.operation_token JOIN stable_source_revision r ON r.singleton=1 WHERE n.operation_token=NEW.operation_token AND n.spreadsheet_id=NEW.spreadsheet_id AND n.state='TIME_VERIFIED' AND n.ready_status=NEW.initial_ready_status AND n.next_stamp=NEW.next_stamp AND c.notice_stamp=n.next_stamp AND c.notice_identity=n.notice_identity AND r.revision=NEW.source_revision AND (((NEW.dispatch_ready_status IN ('พร้อมแก้ไข','พร้อมแก้ไข • กำลังซิงก์') OR substr(NEW.dispatch_ready_status,1,length('พร้อมแก้ไข • กำลังซิงก์ • รหัส '))='พร้อมแก้ไข • กำลังซิงก์ • รหัส ') AND NOT EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW')) OR ((NEW.dispatch_ready_status IN ('พร้อมแก้ไข • มีรายการรอตรวจ','พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ') OR substr(NEW.dispatch_ready_status,1,length('พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส '))='พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส ') AND EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW'))) AND ((n.claim_mode='REVIEW' AND c.state='REVIEW' AND c.phase='OPERATION' AND (NEW.dispatch_ready_status IN ('พร้อมแก้ไข','พร้อมแก้ไข • มีรายการรอตรวจ') OR (n.projection='PUBLICATION' AND n.operation_kind='CANCEL' AND EXISTS(SELECT 1 FROM continuous_revoke_review_close_activation a WHERE a.singleton=1) AND NEW.dispatch_ready_status='พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส '||substr(n.next_stamp,-32)))) OR (n.claim_mode='HANDOFF' AND c.state='HELD' AND c.phase='END_NOTICE_PENDING' AND (NEW.dispatch_ready_status IN ('พร้อมแก้ไข • กำลังซิงก์','พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ') OR substr(NEW.dispatch_ready_status,1,length('พร้อมแก้ไข • กำลังซิงก์ • รหัส '))='พร้อมแก้ไข • กำลังซิงก์ • รหัส ' OR substr(NEW.dispatch_ready_status,1,length('พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส '))='พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส '))))
BEGIN SELECT RAISE(ABORT,'status attempt requires verified notice and current review state'); END;
